 public sealed class NinjaMatch:SportsEventSession
 {
  public LWS.TruckFieldGoal.FieldGoalCrowd crowd;public NinjaCourse course;public SportsEventTruck[] trucks;public NinjaAthlete[] athletes;public SportsFragmentRig[] fragments;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public SportsCameraFit framing;public SportsChaosWeather atmosphere;public SportsRecordedReview review;public NinjaRules rules=new NinjaRules();public Key compressionKey=Key.LeftCtrl;public int ActualBells{get;private set;}public int ActualRecoveries{get;private set;}
  public override string Title=>"TRUCK NINJA WARRIOR";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override int OptionCount=>3;public override int WeatherCount=>1;public override int CompactScoreColumns=>8;public override bool SupportsSplitAIViews=>true;public override bool AISplitViewsApplicable=>false;public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>rules.Phase==NinjaPhase.Countdown?3-rules.StateClock:-1;public override float RaceStartSeconds=>rules.Phase==NinjaPhase.Running?rules.Clock:-1;public override bool ReplayControls=>review!=null&&review.Playing;
  public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=BowlingMode.HotSeat;setup.sharedHotSeat=true;}public override string OptionLabel=>new[]{"THREE-MINUTE RUN","TWO-AND-A-HALF-MINUTE RUN","TWO-MINUTE RUN"}[option];
  public override string Header=>Title+" · "+setup.players[rules.Active].name+" · "+Mathf.Max(0,rules.Limit-rules.Clock).ToString("F1")+"s LEFT";
  public override string Status=>rules.Phase==NinjaPhase.Countdown?"SQUAT. SPRING. SOAR. · GET READY":announcementUntil>age?announcement:rules.Checkpoint>=course.obstacles.Length?"WARPED WALL CLEAR · HIT THE GIANT BELL WITH YOUR BUMPER":course.obstacles[rules.Checkpoint]+" · "+rules.Clock.ToString("F1")+"s + "+rules.Penalty.ToString("F0")+"s PENALTIES";
  public override string ControlCaption(int slot)=>base.ControlCaption(slot).Replace(" ACTION"," JUMP")+" · "+(setup.players[slot].source==BowlingSource.Keyboard?compressionKey.ToString().ToUpperInvariant():setup.players[slot].source==BowlingSource.LeftStick?"D-PAD LEFT":setup.players[slot].source==BowlingSource.RightStick?"D-PAD RIGHT":"EAST")+" HOLD COMPRESS";
  public override string Help=>"Six substantial physical game-show obstacles: tilting steps, rotating logs, swinging wrecking balls, a weight-driven seesaw bridge, spinning discs and the giant curved warped wall. Drive and brake with your assigned source. ACTION jumps. Hold COMPRESSION to lower the actual NWH suspension; release it while jumping for a stronger super-jump. Steering also gives modest leaning, two-wheel balance and bounded air correction. Gravity and forward momentum remain real. Each obstacle has a safe checkpoint after its whole-truck exit. A genuine fall costs exactly5seconds and recovers at the last checkpoint, not the beginning. Hold JUMP for1.2seconds when stuck to recover at the same five-second cost. The2–3minute attempt timer always continues, except during pause. Complete the curved wall and physically hit the giant bell with your front bumper. Fastest adjusted actual time wins; equal times compare falls then share placing. Failed runs rank by obstacles cleared.1–8alternating participants, up to4humans, AI, full-screen active-driver chase/cab/elevated views, free look, horn, crew identities, selected weather, recorded highlights and rematch. AI uses these same movement abilities and checkpoints; no invented scores.";
  public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;for(int i=0;i<setup.count;i++){var p=setup.players[i];if(p.source==BowlingSource.Keyboard&&(compressionKey==p.forward||compressionKey==p.left||compressionKey==p.back||compressionKey==p.right||compressionKey==actionKeys[i])){reason="Compression key conflicts with active driving/jump controls.";return false;}}return true;}
  public override bool TryReadScoreCard(int i,out string value,out string detail){value=rules.finished[i]?rules.adjustedTime[i].ToString("F1")+"s":i==rules.Active?(rules.Clock+rules.Penalty).ToString("F1")+"s":"—";detail=rules.finished[i]?"FINISH · "+rules.falls[i]+" FALLS":rules.cleared[i]+" / "+course.obstacles.Length+" CLEARED";return i<setup.count;}
  readonly StringBuilder text=new StringBuilder(900);public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append('#').Append(rules.Place(i)).Append(' ').Append(setup.players[i].name).Append(" · ").Append(rules.finished[i]?rules.adjustedTime[i].ToString("F2")+"s":"DNF").Append(" · ").Append(rules.cleared[i]).Append(" OBSTACLES · ").Append(rules.falls[i]).Append(" FALLS\n");return text.ToString();}}public override string Results=>"GAME-SHOW FINAL TIMES\n\n"+Standings;
  readonly FareFightRoute driver=new FareFightRoute();readonly NinjaProgressWatch recoveryProgress=new NinjaProgressWatch();int prepared=-1;float age,announcementUntil,recoveryUntil;string announcement="";float priorRear,stuckFor,recoveryHeld;float lastJumpZ=-1000;readonly float[] jumpZones={2,34,62,89,134,176,225,359,422,485,519,642};
  protected override void BeginGame(){rules.Reset(setup.count,course.obstacles.Length,new[]{180f,150,120}[option]);rules.Begin();age=0;announcement="";announcementUntil=0;feedback.StopAll();crowd?.ResetAttempt();ActualBells=ActualRecoveries=0;prepared=-1;atmosphere.Configure(Environment.TickCount,0,1);if(review==null){review=gameObject.AddComponent<SportsRecordedReview>();review.match=this;review.trucks=trucks;review.fragments=fragments;review.drivingViews=drivingViews;review.broadcast=broadcast;review.framing=framing;review.atmosphere=atmosphere;review.watchAction="watchninja";review.extras=new[]{course.motionGroup};}review.ResetRecord();Prepare();}
  void Prepare(){prepared=rules.Active;course.ResetCourse();recoveryUntil=stuckFor=recoveryHeld=0;lastJumpZ=-1000;driver.Reset();driver.groundNormalThreshold=.4f;driver.speedScale=12f/(setup.players[rules.Active].difficulty==BowlingDifficulty.Easy?9:setup.players[rules.Active].difficulty==BowlingDifficulty.Normal?12:15);for(int i=0;i<trucks.Length;i++){fragments[i].ResetBody();trucks[i].gameObject.SetActive(i==rules.Active);if(i!=rules.Active)continue;trucks[i].tractorMotor.Configure();var damage=trucks[i].GetComponent<NWH.VehiclePhysics2.Damage.DamageHandler>();if(damage!=null){damage.meshDeform=false;damage.Repair();}athletes[i].ResetAthlete();trucks[i].Prepare(course.start,Quaternion.identity);Hold(trucks[i]);}var groups=new int[setup.count];Array.Fill(groups,rules.Active);drivingViews.rally.presentationGroups=groups;drivingViews.rally.Focus=rules.Active;drivingViews.Layout();priorRear=Rear(trucks[rules.Active]);recoveryProgress.Reset(trucks[rules.Active].body.position);Gate();Physics.SyncTransforms();}
  static float Rear(SportsEventTruck t){float z=float.PositiveInfinity;foreach(var c in t.GetComponentsInChildren<Collider>())if(c.enabled&&!c.isTrigger&&c.attachedRigidbody==t.body)z=Mathf.Min(z,c.bounds.min.z);return z;}
  static void Hold(SportsEventTruck t){t.TickDrive(Vector2.zero);var input=t.tractorMotor.vehicle.input;input.states.handbrake=input.states.handbrakeRaw=1;}
  protected override void Simulate(float dt)
  {
   age+=dt;var before=rules.Phase;rules.Tick(dt);if(rules.Complete){EndMatch();return;}if(prepared!=rules.Active)Prepare();if(before==NinjaPhase.Countdown&&rules.Phase==NinjaPhase.Running)course.Release();atmosphere.Tick(age);if(rules.Phase==NinjaPhase.Running)course.Step(rules.Clock);review.Capture(age);var t=trucks[rules.Active];if(rules.Phase!=NinjaPhase.Running){Hold(t);return;}
   bool aiSource=setup.players[rules.Active].source==BowlingSource.AI;recoveryProgress.Step(t.body.position,dt);stuckFor=recoveryProgress.Seconds;recoveryHeld=!aiSource&&setup.players[rules.Active].released&&ActionHeld(rules.Active)?recoveryHeld+dt:0;bool water=t.body.position.y<course.waterLevel+1||Mathf.Abs(t.body.position.x)>65;bool trapped=stuckFor>6;bool request=stuckFor>2&&recoveryHeld>1.2f;
   if(water||aiSource&&trapped||request){if(age>=recoveryUntil)RecoverAtCheckpoint(t,water?"SPLASH!":"STUCK RECOVERY");return;}
   float rear=Rear(t);if(rules.Checkpoint<course.checkpoints.Length){var point=course.checkpoints[rules.Checkpoint];if(priorRear<point.z&&rear>=point.z&&t.body.position.y>=point.y-2&&Mathf.Abs(t.body.position.x-point.x)<20){rules.Clear(rules.Active,rules.Checkpoint+1);feedback.PlayAt(1,t.body.position,0,false);crowd?.React(true,"CHECKPOINT",t.body.position);Announce("CHECKPOINT "+rules.Checkpoint+" · SAFE RECOVERY");}}
   bool ai=setup.players[rules.Active].source==BowlingSource.AI;bool compress=ai?false:CompressHeld(rules.Active);bool jump=!ai&&actions[rules.Active];var command=ai?Bot(t,out compress,out jump,dt):commands[rules.Active];t.tractorMotor.gripScale=atmosphere.Grip;athletes[rules.Active].Step(command,compress,jump,dt,rules.Clock);priorRear=rear;
  }
  void RecoverAtCheckpoint(SportsEventTruck t,string reason){rules.Fall(rules.Active);ActualRecoveries++;crowd?.React(false,"FALL",t.body.position);var at=rules.Checkpoint==0?course.start:course.checkpoints[rules.Checkpoint-1];athletes[rules.Active].Recover(rules.Clock);t.GetComponent<NWH.VehiclePhysics2.Damage.DamageHandler>()?.Repair();t.Prepare(at,Quaternion.identity);priorRear=Rear(t);driver.Reset();lastJumpZ=rules.Checkpoint==3?359:-1000;stuckFor=recoveryHeld=0;recoveryProgress.Reset(t.body.position);recoveryUntil=age+1.2f;Announce(reason+" +5 SECONDS · CHECKPOINT "+rules.Checkpoint);}
  bool CompressHeld(int i){var p=setup.players[i];if(p.source==BowlingSource.Keyboard)return SportsDeviceInput.KeyHeld(compressionKey);if(p.pad==null)return false;return p.source==BowlingSource.WholeController?p.pad.buttonEast.isPressed:p.source==BowlingSource.LeftStick?p.pad.dpad.left.isPressed:p.source==BowlingSource.RightStick&&p.pad.dpad.right.isPressed;}
  Vector2 Bot(SportsEventTruck t,out bool compress,out bool jump,float dt)
  {
   var target=rules.Checkpoint<course.checkpoints.Length?course.checkpoints[rules.Checkpoint]+Vector3.forward*5:course.bell.position;driver.DirectGoal(t.body.position,target);Rigidbody permitted=rules.Checkpoint==5?course.finaleLanding:rules.Checkpoint>=6?course.bell:null;if(rules.Checkpoint==0){float nearest=float.PositiveInfinity;foreach(var body in course.movingBodies)if(body.name.StartsWith("Weight-tilting giant step")&&body.position.z>t.body.position.z+2&&body.position.z<nearest){nearest=body.position.z;permitted=body;}}var command=driver.Drive(t.body,t.transform,(int)setup.players[rules.Active].difficulty,dt,atmosphere.Grip,permitted,rules.Checkpoint==5?course.warpedWall:null);compress=jump=false;
   bool ground=Array.Exists(t.wheels,w=>w.IsGrounded);float z=t.body.position.z,launch=float.PositiveInfinity;foreach(float at in jumpZones)if(at>lastJumpZ+.5f&&at>=z-2){launch=at;break;}if(rules.Checkpoint==3&&lastJumpZ==359&&z<372)launch=372;float distance=launch-z;
   // Choose real launch edges from the authored course. These are input
   // decisions: the athlete still requires grounded wheels, charge and cooldown.
   // Counter the measured sideways motion of genuine rolling/spinning decks
   // through ordinary steering. No lateral force or position correction.
   if(ground&&(rules.Checkpoint==1||rules.Checkpoint==4)){float centre=rules.Checkpoint==1?0:Mathf.Clamp((z-510)/34*4,-4,4);command.x=Mathf.Clamp(command.x-t.body.linearVelocity.x*.2f-(t.body.position.x-centre)*.06f,-.8f,.8f);}
   bool needsSuper=launch==89||launch==422||launch==642;
   if(distance<12){compress=needsSuper;if(ground&&distance<3&&(!needsSuper||athletes[rules.Active].Compression>.65f)){compress=false;jump=true;lastJumpZ=launch;}else if(ground&&needsSuper&&distance<2)command.y=-.25f;}
   return command;
  }
  public void StrikeBell(int slot){if(!Live||!rules.Bell(slot))return;ActualBells++;crowd?.React(true,"VICTORY BELL",course.bell.position);float best=SportsPrefs.GetFloat("TruckNinjaWarrior.BestSeconds",float.PositiveInfinity);if(rules.adjustedTime[slot]<best){SportsPrefs.SetFloat("TruckNinjaWarrior.BestSeconds",rules.adjustedTime[slot]);SportsPrefs.Save();}feedback.PlayAt(6,course.bell.position,0,true);Announce("DING! "+setup.players[slot].name+" · "+rules.adjustedTime[slot].ToString("F2")+"s");}
  public string DriveTelemetry=>"desired="+driver.DesiredSpeed+" obstacle="+driver.BlockingObstacle+" stationary="+recoveryProgress.Seconds;
  void Announce(string value){announcement=value;announcementUntil=age+3;}
  protected override void Present(float dt){if(drivingViews==null)return;if(ReplayControls){review.Tick();return;}drivingViews.Tick(dt);if(drivingViews.NeedsArena){var t=trucks[rules.Active];broadcast.Pose(t.body.position+Vector3.forward*9,new Vector3(25,23,-31),69);}}
  public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();else review?.Action(key);}protected override void SetPaused(bool pause){atmosphere?.Pause(pause);}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}
  protected override void StopGame(){review?.End(false);StopSounds();if(athletes!=null)foreach(var a in athletes)a.Restore();if(trucks!=null)foreach(var t in trucks){t.Power(false);if(!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=true;}}
